#### STD-FE-014: Jest as the Unit Test Runner

**MUST** use Jest as the unit and component test runner for all Webpack-based React applications. Do not use Vitest in new Webpack applications.

```bash
npm install --save-dev jest @jest/globals jest-environment-jsdom ts-jest @testing-library/react @testing-library/user-event @testing-library/jest-dom
```

```typescript
// jest.config.ts
import type { Config } from 'jest';

const config: Config = {
  preset: 'ts-jest',
  testEnvironment: 'jsdom',
  setupFilesAfterFramework: ['<rootDir>/src/test/setup.ts'],
  collectCoverageFrom: ['src/**/*.{ts,tsx}', '!src/test/**', '!src/**/*.stories.tsx'],
  coverageReporters: ['text', 'lcov'],
};

export default config;
```

```typescript
// src/test/setup.ts
import '@testing-library/jest-dom';
```

